# owner: platform
"""Stretches of opening hours that nobody is covering."""

from typing import Iterable, Iterator, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans


def _check_inside(worked: List[Span], opening: Span):
    for span in worked:
        before = span.start < opening.start
        if before or span.end > opening.end:
            text = format_span(span)
            raise ValueError(f"{text} is outside opening")


def _holes(
    covered: List[Span], opening: Span
) -> Iterator[Span]:
    cursor = opening.start
    for span in covered:
        if span.start > cursor:
            yield Span(cursor, span.start)
        cursor = span.end
    if cursor < opening.end:
        yield Span(cursor, opening.end)


def _label(span: Span) -> str:
    return f"gap {format_span(span)} ({span.minutes} min)"


# ---
def find_gaps(
    worked: Iterable[Span], opening: Span
) -> List[str]:
    worked = list(worked)
    _check_inside(worked, opening)
    covered = merge_spans(worked)
    holes = _holes(covered, opening)
    return [_label(hole) for hole in holes]

